NUM_COLUMNS = 5
MAX_POSITION = 3  # reaching this loses the game


class Policy:
    name = "deep_lookahead_feasibility"

    # --------------------------------------------------------------- #
    def choose_action(self, engine):
        # ----- snapshot -----
        cannons = {c: engine.cannons[c].damage for c in engine.cannons}
        pirates = [
            {"column": p.column, "position": p.position, "hp": p.hp}
            for p in engine.pirates
        ]

        # ----- helpers -------------------------------------------------
        def simulate_round(cannons_map, pirates_list):
            """Apply damage (front pirate per column) then advance pirates."""
            cann = dict(cannons_map)
            pir = [dict(p) for p in pirates_list]

            # damage phase
            for col, dmg in cann.items():
                if dmg <= 0:
                    continue
                col_p = [p for p in pir if p["column"] == col]
                if not col_p:
                    continue
                front = max(col_p, key=lambda p: p["position"])
                front["hp"] -= dmg
                if front["hp"] <= 0:
                    pir.remove(front)

            # advance phase
            for p in pir:
                p["position"] += 1

            loss = any(p["position"] >= MAX_POSITION for p in pir)
            return cann, pir, loss

        def possible_damage(dmg, col_pirates):
            """Damage that a fixed‑damage cannon can deliver before loss."""
            pirates = [dict(p) for p in col_pirates]
            total = 0
            while pirates:
                front = max(pirates, key=lambda p: p["position"])
                front["hp"] -= dmg
                total += dmg
                if front["hp"] <= 0:
                    pirates.remove(front)
                for p in pirates:
                    p["position"] += 1
                if any(p["position"] >= MAX_POSITION for p in pirates):
                    break
            return total

        def total_deficit(cannons_map, pirates_list):
            """HP that cannot be eliminated with current cannon damage."""
            deficit = 0
            cols = {c: [] for c in range(NUM_COLUMNS)}
            for p in pirates_list:
                cols[p["column"]].append(p)

            for col, plist in cols.items():
                if not plist:
                    continue
                dmg = cannons_map.get(col, 0)
                possible = possible_damage(dmg, plist)
                total_hp = sum(p["hp"] for p in plist)
                if total_hp > possible:
                    deficit += total_hp - possible
            return deficit

        def evaluate_state(cannons_map, pirates_list):
            """Return (deficit, max_position)."""
            return total_deficit(cannons_map, pirates_list), max(
                (p["position"] for p in pirates_list), default=-1
            )

        def required_extra_damage(cannons_map, pirates_list):
            """Extra 1‑damage points (from future spawns) needed to survive."""
            extra = 0
            for p in pirates_list:
                col = p["column"]
                dmg_per_round = cannons_map.get(col, 0)
                rounds_left = MAX_POSITION - p["position"]
                # damage that will be dealt by existing cannon before loss
                dmg_from_cannon = dmg_per_round * rounds_left
                need = max(0, p["hp"] - dmg_from_cannon)
                extra += need
            return extra

        def feasible(cannons_map, pirates_list, remaining_rounds):
            """Optimistic check: can remaining extra damage points cover needs?"""
            need = required_extra_damage(cannons_map, pirates_list)
            return need <= remaining_rounds

        # ----- action enumeration (deterministic order) -----
        actions = []
        for col in range(NUM_COLUMNS):
            actions.append(("spawn", col))
        for donor in sorted(cannons):
            for target in range(NUM_COLUMNS):
                if donor == target:
                    continue
                actions.append(("move", donor, target))

        # ----- depth‑limited search ----------------------------------
        def dfs(cannons_map, pirates_list, depth):
            """Return best (deficit, maxpos) reachable within `depth` rounds."""
            if depth == 0:
                return evaluate_state(cannons_map, pirates_list)

            # prune hopeless states early
            if not feasible(cannons_map, pirates_list, depth):
                # return a very bad score
                return (10 ** 9, 10 ** 9)

            best_key = (10 ** 9, 10 ** 9)

            # generate possible actions for this round
            possible = []
            for col in range(NUM_COLUMNS):
                possible.append(("spawn", col))
            for donor in cannons_map:
                for target in range(NUM_COLUMNS):
                    if donor == target:
                        continue
                    possible.append(("move", donor, target))

            for act in possible:
                new_cann = dict(cannons_map)

                if act[0] == "spawn":
                    col = act[1]
                    new_cann[col] = new_cann.get(col, 0) + 1
                else:  # move
                    donor, target = act[1], act[2]
                    dmg = new_cann.pop(donor)
                    new_cann[target] = new_cann.get(target, 0) + dmg
                    # the pending spawn stays unused – it will be available next round

                post_cann, post_pir, loss = simulate_round(new_cann, pirates_list)
                if loss:
                    continue

                key = dfs(post_cann, post_pir, depth - 1)
                if key < best_key:
                    best_key = key

            return best_key

        # ----- evaluate each immediate action -------------------------
        best_action = None
        best_score = None

        for act in actions:
            # apply action
            new_cann = dict(cannons)
            if act[0] == "spawn":
                col = act[1]
                new_cann[col] = new_cann.get(col, 0) + 1
            else:  # move
                donor, target = act[1], act[2]
                dmg = new_cann.pop(donor)
                new_cann[target] = new_cann.get(target, 0) + dmg

            post_cann, post_pir, loss = simulate_round(new_cann, pirates)
            if loss:
                continue

            # look ahead two more rounds (total depth = 2)
            score = dfs(post_cann, post_pir, depth=2)

            # tie‑break with deterministic order (the loop order already does this)
            if best_score is None or score < best_score:
                best_score = score
                best_action = act

            # early exit if we have a perfect state
            if score == (0, -1):
                break

        # fallback – should never happen
        if best_action is None:
            for col in range(NUM_COLUMNS):
                if col not in engine.cannons:
                    return ("spawn", col)
            return ("spawn", 0)

        return best_action
